-- LOCAL DEVELOPMENT SEED ONLY (supabase db reset). Synthetic prices; never run in production.
update public.cards c set counterpart_card_id = o.id from public.cards o
 where c.game = 'one-piece' and o.game = 'one-piece' and c.number = o.number and c.lang <> o.lang;
update public.cards c set counterpart_card_id = (select id from public.cards where lang='jp' and number='201')
 where c.lang='en' and c.number='199';
update public.cards c set counterpart_card_id = (select id from public.cards where lang='en' and number='199')
 where c.lang='jp' and c.number='201';
refresh materialized view public.market_cap_rankings;

